set -E
trap 'echo "[err]"' ERR
coproc { trap -p ERR; false; echo "after false"; }
cat <&${COPROC[0]}
wait

trap 'echo "[return]"' RETURN
myfunc() {
  echo "in func"
}
myfunc
echo "after func"

set +T
trap 'echo "[return]"' RETURN
outer() {
  inner() {
    echo "in inner"
  }
  inner
  echo "after inner"
}
outer
echo "done"

trap 'echo "[return]"' RETURN
(
  myfunc() { echo "in func"; }
  myfunc
)
echo "after subshell"

f() { trap 'echo "ret $?"' RETURN; false; }
f
echo "status $?"
